if (horasDesde >= 24 && horasDesde <= 72) {
  return [{ json: lead }];
}
return [];

const lead = $('Evaluar Ventana Seguimiento').item.json;
const instancia = ($json && $json[0]) || {};
const autoTexto = lead.auto_interes ? `el ${lead.auto_interes}` : 'alguna de nuestras unidades';
const mensaje = `¡Hola ${lead.nombre || ''}! 👋 Vi que te interesaba ${autoTexto} — ¿sigue en tus planes? Si tienes dudas o quieres agendar para verlo en persona, aqui ando para ayudarte. 🚗`;
return [{ json: { leadId: lead.id, telefono: lead.phone_number, instanceName: instancia.instance_name || null, apiKey: instancia.api_key || null, mensaje } }];

const precio = $fromAI('precio', 'Precio total de venta del auto en pesos mexicanos', 'number');
const enganche = $fromAI('enganche', 'Monto del enganche que el cliente va a dar en pesos mexicanos', 'number');
const plazoMeses = $fromAI('plazo_meses', 'Plazo en meses que pidio el cliente; si no lo menciono usa 48', 'number') || 48;

// NOTA: ajusta TASA_ANUAL a la tasa real de tu financiera antes de producción
const TASA_ANUAL = 0.24;

const principal = Math.max((precio || 0) - (enganche || 0), 0);
const tasaMensual = TASA_ANUAL / 12;
const mensualidad = tasaMensual === 0
  ? principal / plazoMeses
  : (principal * tasaMensual) / (1 - Math.pow(1 + tasaMensual, -plazoMeses));

return `Mensualidad estimada a ${plazoMeses} meses: $${mensualidad.toFixed(2)} MXN (aproximada, sujeta a aprobacion de credito y a la tasa real que ofrezca la financiera).`;

const crypto = require('crypto');
const lote = $json;
// 24 bytes aleatorios: token hexadecimal de 48 caracteres.
const token = crypto.randomBytes(24).toString('hex');
return [{ json: {
  lote_id: lote.id,
  nombre: lote.nombre,
  whatsapp_number: lote.whatsapp_number,
  token_anterior: lote.webhook_token,
  token_nuevo: token
} }];

