const event = $('Webhook WhatsApp1').first().json.body || {};
const data = event.data || {};
const channel = $('Get many rows1').first().json || {};
const jid = String(data.key?.remoteJid || '');
const phone = jid.split('@')[0].replace(/:\d+$/, '').replace(/^521|^52/, '').replace(/[^0-9]/g, '');
const source = String(data.source || '').toLowerCase();
const fromMe = data.key?.fromMe === true;
const body = data.message || {};
const text = body.conversation || body.extendedTextMessage?.text || body.imageMessage?.caption || body.videoMessage?.caption || body.documentMessage?.caption || (data.messageType ? '[' + data.messageType + ']' : '[Mensaje]');
if (!channel.lote_id || !phone || jid.includes('@g.us')) return [{ json: { tipo: 'ignorar' } }];
const tipo = !fromMe ? 'cliente' : (source && source !== 'unknown' ? 'humano' : 'salida_api');
return [{ json: { tipo, lote_id: String(channel.lote_id), phone_number: phone, content: String(text).slice(0, 12000), message_id: data.key?.id || null, source } }];

const rows = $input.all().map(item => item.json).flatMap(value => Array.isArray(value) ? value : [value]);
const state = rows.find(row => row && row.manual_until) || null;
const event = $('Webhook WhatsApp1').first().json.body || {};
const data = event.data || {};
const channel = $('Get many rows1').first().json || {};
const jid = String(data.key?.remoteJid || '');
const phone = jid.split('@')[0].replace(/:\d+$/, '').replace(/^521|^52/, '').replace(/[^0-9]/g, '');
const message = data.message || {};
const content = message.conversation || message.extendedTextMessage?.text || message.imageMessage?.caption || message.videoMessage?.caption || message.documentMessage?.caption || (data.messageType ? '[' + data.messageType + ']' : '[Mensaje]');
const until = state?.manual_until ? Date.parse(state.manual_until) : 0;
return [{ json: { manual_activo: Number.isFinite(until) && until > Date.now(), lote_id: String(channel.lote_id || ''), phone_number: phone, content: String(content).slice(0, 12000) } }];
